function UIChooseCookingFoodNode:Refresh(data, ind, cb, levelId)
    if not data then
        return
    end
    self._data = data
    self._cb = cb
    self._levelId = checkNumber(levelId)
    self._levelType = GoodsUtils.GetIdType(self._levelId, Constants.IDArea.Quests)

    CfUtils.PlayDelayShowAnimate(self.AnimRoot, ind)

    self:FillSelf()

    KTool.SetActive(self.AnimRoot.transform:Find("ImgNew"), CookingUtils.IsNewRecipe(self._data.menu))
end

function UIChooseCookingFoodNode:FillSelf()
    CfUtils.FillText(self.TextName, self._data.name)
    CfUtils.FillImage(self.ImgIcon, GoodsConfMgr:GetInstance():GetPhotoPathById(self._data.id))
    CfUtils.FillFontStyleWithGoodIconButtonNode(self.BtnBuy, self._data.goodsConsum, "x"..self._data.goodsConsumNum)
    self:FillCollectInfo()

    local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(self._data.id)
    CfUtils.FillImage(self.AnimRoot.transform:Find("IconGroup/ImgType"), StoreUtils.GetGoodsBgByQuality(vo.quality))

    local curNum = GoodsUtils.GetThingNo(self._data.id)
    CfUtils.FillText(self.Text, curNum)
    CfUtils.SetUISwitchText(self.Text, curNum <= 0 and 2 or 1)

    local isUse, num = CookingUtils.IsUseBattleFood(self._data.id)
    KTool.SetActive(self.Black, isUse)

    local isUnlock = CookingUtils.IsUnlockFood(self._data.id)
    KTool.SetActive(self.BlackLock, not isUnlock)

    if not isUnlock then
        CfUtils.SetActive(self.FontStyleButton, true)
        self.FontStyleButton:ResetFontStyle("B7", localize("前往解锁"))
        SetButtonAction(self.FontStyleButton, function()
            GameUtils.Toast(localize("通过垂钓获得"))
            --[[
            local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(self._data.menu)
            if isSet(goodsVo, "jumpAway") and table.count(goodsVo.jumpAway) > 0 then
                local row = GoodsConfMgr:GetInstance():GetJumpModuleRow(goodsVo.jumpAway[1])
                GoodsConfMgr:GetInstance():ExecuteJump(row, goodsVo, 1)
            end
            ]]
        end)
    elseif isUse then
        CfUtils.SetActive(self.FontStyleButton, false)
    else
        CfUtils.SetActive(self.FontStyleButton, true)
        --if curNum > 0 then
            self.FontStyleButton:ResetFontStyle("B6", localize("使用"))
            SetButtonAction(self.FontStyleButton, Bind(self, self.OnBtnUse))
        --else
        --    self.FontStyleButton:ResetFontStyle("B6", localize("购买"))
        --    KTool.SetActive(self.CommonBtnConsumePop, true)
        --    CfUtils.FillCommonBtnConsumePopNode(self.CommonBtnConsumePop, self._data.goodsConsum, self._data.goodsConsumNum)
        --    SetButtonAction(self.FontStyleButton, Bind(self, self.OnBtnBuy))
        --end
    end

    self:FillBuffDescs()

    local status = isUnlock and 1 or 2
    CfUtils.SetUISwitchText(self.TextName, status)
end

function UIChooseCookingFoodNode:FillBuffDescs()
    local t = {}
    local t1= CookingUtils.GetBattleFoodEffectDesc(self._data.id)
    local t2 = CfUtils.Split(self._data.desc, ";")
    --table.insert(t, t1[1])
    for k, v in pairs(t2) do
        table.insert(t, v)
    end
    local isUnlock = CookingUtils.IsUnlockFood(self._data.id)

    for i = 1, self.Content.transform.childCount do
        local go = self.Content.transform:GetChild(i - 1)
        if go then
            CfUtils.SetActive(go, false)
        end
    end

    KTool.SetActive(self.Cell, false)
    for k, v in pairs(t) do
        local go = self.Content.transform:Find("buff"..k)
        if not go then
            go = CfUtils.InstantiateGo(self.Cell, self.Content)
            go.name = "buff"..k
        end
        local status = (k == 1 and 2 or 1)
        CfUtils.SetUISwitchText(go.transform:Find("TextdDesc"), status)
        CfUtils.SetUISwitchImage(go.transform:Find("ImgSquare"), status)

        CfUtils.FillText(go.transform:Find("TextdDesc"), v)
        CfUtils.SetUISwitchText(go.transform:Find("TextdDesc"), isUnlock and 1 or 2)
        KTool.SetActive(go, true)
    end 
end

--收藏的信息
function UIChooseCookingFoodNode:FillCollectInfo()
    local isCollect = CookingUtils.IsCollectFood(self._data.id)
    local status = isCollect and 2 or 1
    CfUtils.SetUISwitchImage(self.BtnCollect, status)
end

--收藏
function UIChooseCookingFoodNode:OnBtnCollect()
    local isCollect = CookingUtils.IsCollectFood(self._data.id)
    CookingUtils.SetCollectStatusFood(self._data.id, not isCollect)
    self:FillCollectInfo()
end

--购买
function UIChooseCookingFoodNode:OnBtnBuy()
    local isUnlock = CookingUtils.IsUnlockFood(self._data.id)
    if not isUnlock then
        --GameUtils.Toast(localize("该物品未解锁"))
        GameUtils.Toast(localize("通过垂钓获得"))
        return
    end
    CookingUtils.RemoveRedPointMapById(self._data.menu)
    --if self._cb then
    --    self._cb()
    --end

    local t = {
        goodsId = self._data.id,
        consumeGoodsId = self._data.goodsConsum,
        remainTime = 0,
        consumeNum = self._data.goodsConsumNum,
        maxBuyNum = 99,
        buyCb = function(num)
            comp:CookingBuyBattleCookingReq(self._data.id, num, function()
                UIModule.OpenDialog({ id = Constants.UITypeIds.UICultivateLevelUpFinishDialog, parameters = {
                    foodId = self._data.id,
                    levelUpType = Constants.UICultivateLevelUpFinishType.CookingFood
                }})

                CookingUtils.RemoveRedPointMapById(self._data.menu)
                comp:CookingSetBattleFoodReq(self._data.id, function(lastUseId)
                    if self._cb then
                        self._cb(lastUseId)
                    end
                    self:FillSelf()
                end)
            end)
        end,
    }
    UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonBuyItemDialog, parameters = t}, {
    })
end

--使用
function UIChooseCookingFoodNode:OnBtnUse()
    local curNum = GoodsUtils.GetThingNo(self._data.id)
    --没有去购买
    if curNum <= 0 then
        self:OnBtnBuy()
    else
        CookingUtils.RemoveRedPointMapById(self._data.menu)
        comp:CookingSetBattleFoodReq(self._data.id, function()
            UIModule.BackDialog()
        end)
    end
end

function UIChooseCookingFoodNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIChooseCookingFoodNode
